// ============================================================
// Extract, Filter, Tag & Sanitize -- single email in, single item out.
// This node is deliberately trigger-agnostic: it only assumes the input
// is a Microsoft Graph "message" resource, so it works identically whether
// it was handed to us by the Outlook Trigger (real-time) or by the
// Reconciliation workflow's getAll (safety net).
// ============================================================
const item = $input.first().json;

const SELF_SENDER_MATCHES = [
  "itsupport@nextgeninnov8.com",
  "itsupport_nextgeninnov8_com"
];

const AUTO_REPLY_SUBJECT_PREFIXES = [
  "automatic reply:", "auto:", "out of office", "undeliverable:",
  "read:", "delivery status notification", "mail delivery failed"
];

const HIGH_PRIORITY_KEYWORDS = [
  "urgent", "asap", "critical", "down", "outage", "emergency",
  "not working", "cannot work", "can't work", "blocked",
  "security breach", "breach", "data loss", "production down",
  "server down", "all hands", "cannot access", "can't access"
];

const LOW_PRIORITY_KEYWORDS = [
  "whenever", "no rush", "minor", "question", "inquiry",
  "when you get a chance", "low priority", "just curious", "fyi"
];

function detectPriority(subject, body) {
  const text = `${subject} ${body}`.toLowerCase();
  if (HIGH_PRIORITY_KEYWORDS.some((k) => text.includes(k))) return "High";
  if (LOW_PRIORITY_KEYWORDS.some((k) => text.includes(k))) return "Low";
  return "Medium";
}

function isSelfSent(senderEmail) {
  const lower = (senderEmail || "").toLowerCase();
  return SELF_SENDER_MATCHES.some((s) => lower.includes(s.toLowerCase()));
}

function isAutoReply(subject) {
  const lower = (subject || "").trim().toLowerCase();
  return AUTO_REPLY_SUBJECT_PREFIXES.some((prefix) => lower.startsWith(prefix));
}

// --- Sender ---
const fromObj = item.from || item.sender || {};
const emailAddrObj = fromObj.emailAddress || fromObj;
let senderEmail = "";
if (typeof emailAddrObj === "string") {
  senderEmail = emailAddrObj;
} else {
  senderEmail = emailAddrObj.address || emailAddrObj.email || fromObj.address || "";
}
let senderName = "";
if (typeof emailAddrObj === "object") {
  senderName = emailAddrObj.name || fromObj.name || "";
}
if (!senderName || senderName.trim() === "" || senderName === senderEmail) {
  if (senderEmail && senderEmail.includes("@")) {
    const namePart = senderEmail.split("@")[0];
    senderName = namePart.replace(/[._-]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
  } else {
    senderName = "Valued User";
  }
}

// --- CC recipients (preserved for the acknowledgement + stored for traceability) ---
const ccEmails = (item.ccRecipients || [])
  .map((r) => {
    const addr = r.emailAddress || r;
    return addr.address || addr.email || "";
  })
  .filter(Boolean)
  .join("; ");

// --- Action decision ---
let action = "process";
let dropReason = null;
if (isSelfSent(senderEmail)) {
  action = "drop";
  dropReason = "Self-sent (loop prevention)";
} else if (isAutoReply(item.subject)) {
  action = "drop";
  dropReason = "Automated/system message (out-of-office, bounce, read receipt, etc.)";
}

// --- Sanitize body ---
let rawBody = item.bodyPreview || item.body?.content || "";
let cleanedBody = rawBody
  .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, "")
  .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, "")
  .replace(/<[^>]*>/g, "")
  .replace(/\r\n/g, "\n")
  .replace(/\r/g, "\n")
  .split("\n").map((l) => l.trim()).filter((l) => l.length > 0).join("\n\n");
if (cleanedBody.length > 1500) cleanedBody = cleanedBody.substring(0, 1497) + "...";

const priority = action === "process" ? detectPriority(item.subject || "", cleanedBody) : null;

return {
  json: {
    messageId: item.id,
    conversationId: item.conversationId,
    internetMessageId: item.internetMessageId,
    conversationIndex: item.conversationIndex || "",
    subject: item.subject || "(no subject)",
    senderName,
    senderEmail,
    ccEmails,
    bodyPreview: cleanedBody || "(no content)",
    receivedDateTime: item.receivedDateTime || item.createdDateTime,
    priority,
    action,
    dropReason
  }
};

// Anchor node for this item's entire processing lifecycle.
// Every later node recovers stable business fields via
// $('Generate Lock Token').item.json rather than relying on passthrough,
// because the Excel/Outlook API-call nodes further down each replace
// $json with their own response and would otherwise wipe this data.
const item = $input.first().json;
const lockToken = `${$execution.id}-${Date.now()}-${Math.random().toString(36).substring(2, 8)}`;
return { json: { ...item, lockToken, lockAttempt: 0 } };

// Runs right after "Read Lock Status" (an Excel Lookup, which replaced
// $json with just the lock row). Recover the retry counter from
// "Wait Before Retry" if we've looped at least once; default to 0 on
// the very first pass, when that node hasn't executed yet in this run.
const lockRow = $input.first().json;

let priorAttempt = 0;
try {
  priorAttempt = $('Wait Before Retry').item.json.lockAttempt || 0;
} catch (e) {
  priorAttempt = 0; // first pass -- Wait Before Retry hasn't run yet
}

const STALE_MS = 30 * 1000; // critical section is short; 30s means the previous holder crashed.
const lockedAt = lockRow.LockedAt ? new Date(lockRow.LockedAt).getTime() : null;
const isLocked = lockRow.LockStatus === "Locked";
const ageMs = lockedAt ? Date.now() - lockedAt : Infinity;
const isStale = ageMs > STALE_MS;
const isAvailable = !isLocked || isStale;

return { json: { isAvailable, lockAttempt: priorAttempt } };

// Runs right after "Verify Lock Ownership" (Excel Lookup). "Evaluate Lock"
// always executes immediately before this in every single pass of this
// loop, so referencing it by name is unambiguous (not a self-reference).
const verifyRow = $input.first().json;
const myToken = $('Generate Lock Token').item.json.lockToken;
const lockAttempt = $('Evaluate Lock').item.json.lockAttempt || 0;
const ownershipConfirmed = verifyRow.LockOwner === myToken;
return { json: { ownershipConfirmed, lockAttempt } };

// Reached from either "lock not available" or "lost the ownership race".
// Both predecessors pass lockAttempt through untouched (IF nodes don't
// transform data), so we can read it straight off the input.
const priorAttempt = $input.first().json.lockAttempt || 0;
const attempt = priorAttempt + 1;

const MAX_ATTEMPTS = 10;
const BASE_MS = 500;
const CAP_MS = 3000;
const jitter = Math.floor(Math.random() * 250);
const waitMs = Math.min(BASE_MS * Math.pow(2, priorAttempt), CAP_MS) + jitter;
const exceededMax = attempt >= MAX_ATTEMPTS;

return { json: { lockAttempt: attempt, waitMs, exceededMax } };

// Dual-key dedupe: existing ticket if EITHER ConversationID OR
// InternetMessageId matched. Guards against Graph occasionally not
// populating conversationId consistently across a thread.
const anchor = $('Generate Lock Token').item.json;
const convMatch = $('Excel - Lookup by ConversationID').first();
const msgIdMatch = $('Excel - Lookup by InternetMessageId').first();

function hasTicket(m) {
  return Boolean(m && m.json && (m.json.TicketID || m.json.ConversationID));
}
const existsByConv = hasTicket(convMatch);
const existsByMsgId = hasTicket(msgIdMatch);
const ticketExists = existsByConv || existsByMsgId;
const existingTicketId =
  (convMatch && convMatch.json && convMatch.json.TicketID) ||
  (msgIdMatch && msgIdMatch.json && msgIdMatch.json.TicketID) ||
  null;

return { json: { ...anchor, ticketExists, existingTicketId } };

// NGI-<ddmmyy>-<XXXX> where XXXX is a random 4-char uppercase alnum string.
// innerAttempt is read from whatever fed us: on the first pass that's
// "IF - Ticket Already Exists?" (no innerAttempt field -> defaults to 0);
// on a retry pass it's "IF - Collision And Retry?" carrying the value
// forward from "Check Ticket ID Collision" untouched.
const anchor = $('Generate Lock Token').item.json;
const innerAttempt = $input.first().json.innerAttempt || 0;

const now = new Date();
const dd = String(now.getDate()).padStart(2, "0");
const mm = String(now.getMonth() + 1).padStart(2, "0");
const yy = String(now.getFullYear()).slice(-2);

const charset = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
let suffix = "";
for (let i = 0; i < 4; i++) suffix += charset[Math.floor(Math.random() * charset.length)];
const candidateTicketId = `NGI-${dd}${mm}${yy}-${suffix}`;

return { json: { ...anchor, candidateTicketId, innerAttempt } };

// Runs right after "Excel - Lookup TicketID Uniqueness". The candidate
// generator always executes immediately before that lookup in every
// pass, so referencing it by name to recover context is unambiguous.
const lookupResult = $input.first();
const genNode = $('Generate Candidate Ticket ID').item.json;
const priorAttempt = genNode.innerAttempt || 0;
const attempt = priorAttempt + 1;

const MAX_INNER_ATTEMPTS = 10; // 36^4 = 1,679,616 combos/day -- this ceiling is just a circuit breaker.
const collision = Boolean(lookupResult && lookupResult.json && lookupResult.json.TicketID);
const exceededMax = attempt >= MAX_INNER_ATTEMPTS;

return {
  json: {
    ...$('Generate Lock Token').item.json,
    candidateTicketId: genNode.candidateTicketId,
    innerAttempt: attempt,
    collision,
    exceededMax
  }
};

const item = $input.first().json;
const errors = [];
if (!item.candidateTicketId) errors.push("Missing candidateTicketId");
if (!item.senderEmail || !item.senderEmail.includes("@")) errors.push("Invalid senderEmail");
if (!item.messageId) errors.push("Missing messageId");
if (!item.conversationId) errors.push("Missing conversationId");
if (!item.subject) errors.push("Missing subject");
return { json: { ...item, isValid: errors.length === 0, validationErrors: errors.join("; ") } };

// "Excel - Create Ticket Row" (an Excel node) just wiped $json with its
// own API response. "Data Guard Validation" always ran immediately
// before it in this single path, so recover from there.
const preCreate = $('Data Guard Validation').item.json;
return { json: { ...preCreate, outcome: "created", ticketId: preCreate.candidateTicketId } };

// Reached after "Read Lock Status Again" (Excel lookup -- wiped $json).
// Four different "Set Outcome - *" nodes could have led here; only one
// of them actually ran this pass. Try each by name and take whichever
// succeeds -- n8n throws a catchable error when referencing a node that
// hasn't executed in the current run, which is exactly what we use here.
function getOutcomeData() {
  const candidates = [
    "Set Outcome - Created",
    "Set Outcome - Duplicate",
    "Set Outcome - Invalid",
    "Set Outcome - ID Exhausted"
  ];
  for (const name of candidates) {
    try {
      const result = $(name).item.json;
      if (result) return result;
    } catch (e) {
      // this branch didn't fire this pass -- try the next candidate
    }
  }
  // Should be unreachable; keeps the run alive instead of crashing.
  return { ...$('Generate Lock Token').item.json, outcome: "unknown" };
}

const recovered = getOutcomeData();
const lockCheckRow = $input.first().json;
const myToken = $('Generate Lock Token').item.json.lockToken;
const stillOwner = lockCheckRow.LockOwner === myToken;

return { json: { ...recovered, stillOwner } };

// "Confirm Ownership & Recover Context" already did the hard work and is
// unambiguous by this point (exactly one instance, already executed).
// This node exists purely so everything downstream (the Switch node's
// rules, Reply/Move node expressions) can use plain {{$json.field}}
// instead of every node needing its own recovery logic.
const recovered = $('Confirm Ownership & Recover Context').item.json;
return { json: { ...recovered } };

const item = $input.first().json;
if (!item.messageId) {
  throw new Error("Missing messageId -- cannot send acknowledgement reply.");
}
return { json: { ...item } };
